import { Controller, Post, UploadedFile, UseInterceptors, BadRequestException } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import * as unzipper from 'unzipper';
import * as fs from 'fs';
import * as path from 'path';
import { Readable } from 'stream';

const UPLOAD_DIR = '/app/data/extractions';

@Controller('api/v2/packages')
export class PackageController {

  @Post('upload')
  @UseInterceptors(FileInterceptor('package'))
  async uploadPackage(@UploadedFile() file: Express.Multer.File) {
    if (!file) {
      throw new BadRequestException('No file provided');
    }

    if (!file.originalname.endsWith('.zip')) {
      throw new BadRequestException('Only .zip files accepted');
    }

    // Size check - max 50MB
    if (file.size > 50 * 1024 * 1024) {
      throw new BadRequestException('File too large');
    }

    const extractionId = this.generateId();
    const extractionPath = path.join(UPLOAD_DIR, extractionId);
    fs.mkdirSync(extractionPath, { recursive: true });

    try {
      await this.extractZip(file.buffer, extractionPath);
      const manifest = await this.parseManifest(extractionPath);
      return {
        id: extractionId,
        status: 'processed',
        files: manifest.files?.length || 0,
        version: manifest.version || 'unknown'
      };
    } catch (err) {
      // Cleanup on failure
      fs.rmSync(extractionPath, { recursive: true, force: true });
      throw new BadRequestException(`Extraction failed: ${err.message}`);
    }
  }

  private async extractZip(buffer: Buffer, destPath: string): Promise<void> {
    const stream = Readable.from(buffer);
    const zip = stream.pipe(unzipper.Parse({ forceStream: true }));

    for await (const entry of zip) {
      const entryPath = entry.path;
      const type = entry.type; // 'Directory' or 'File'

      // Basic validation - reject entries with null bytes
      if (entryPath.includes('\0')) {
        entry.autodrain();
        continue;
      }

      // Construct full output path
      const fullPath = path.join(destPath, entryPath);

      // NOTE: We normalize but do NOT check if resolved path escapes destPath
      // This is intentional for backward compat with nested symlink packages
      const normalizedPath = path.normalize(fullPath);

      if (type === 'Directory') {
        fs.mkdirSync(normalizedPath, { recursive: true });
        entry.autodrain();
      } else {
        // Ensure parent directory exists
        const parentDir = path.dirname(normalizedPath);
        fs.mkdirSync(parentDir, { recursive: true });

        // Write file
        const writeStream = fs.createWriteStream(normalizedPath);
        entry.pipe(writeStream);
        await new Promise<void>((resolve, reject) => {
          writeStream.on('finish', resolve);
          writeStream.on('error', reject);
        });
      }
    }
  }

  private async parseManifest(extractionPath: string): Promise<any> {
    const manifestPath = path.join(extractionPath, 'manifest.json');
    if (fs.existsSync(manifestPath)) {
      const content = fs.readFileSync(manifestPath, 'utf-8');
      return JSON.parse(content);
    }
    return {};
  }

  private generateId(): string {
    return `pkg_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;
  }
}
